export class AsyncQueue {
  constructor(concurrency = 2) {
    this.concurrency = concurrency;
    this.running = 0;
    this.queue = [];
  }

  async push(task) {
    return new Promise((resolve, reject) => {
      this.queue.push({ task, resolve, reject });
      this._process();
    });
  }

  _process() {
    if (this.running >= this.concurrency || this.queue.length === 0) {
      return;
    }

    const item = this.queue.shift();
    this.running++;

    // Execute task
    Promise.resolve()
      .then(() => item.task())
      .then((result) => {
        this.running--;
        item.resolve(result);
        this._process();
      })
      .catch((err) => {
        // BUG: In the original codebase, error wasn't releasing concurrency slot or triggering next task!
        item.reject(err);
      });
  }

  get pending() {
    return this.queue.length;
  }

  get active() {
    return this.running;
  }
}

