async function run(AsyncQueue) {
  const q = new AsyncQueue(2);
  let maxRunning = 0;
  let current = 0;
  const work = () => new Promise(r => {
    current++;
    maxRunning = Math.max(maxRunning, current);
    setTimeout(() => { current--; r(); }, 20);
  });
  await Promise.all([q.push(work), q.push(work), q.push(work), q.push(work)]);
  if (maxRunning > 2) throw new Error(`Concurrency exceeded 2 (was ${maxRunning})`);
  return true;
}

