export class AsyncQueue {
  constructor(concurrency = 2) {
    this.concurrency = concurrency;
    this.running = 0;
    this.queue = [];
  }

  async push(task) {
    return new Promise((resolve, reject) => {
      this.queue.push({ task, resolve, reject });
      this._process();
    });
  }

  _process() {
    if (this.running >= this.concurrency || this.queue.length === 0) {
      return;
    }

    const item = this.queue.shift();
    this.running++;

    Promise.resolve()
      .then(() => item.task())
      .then(
        (res) => ({ ok: true, res }),
        (err) => ({ ok: false, err })
      )
      .then((outcome) => {
        this.running--;
        this._process();
        if (outcome.ok) {
          item.resolve(outcome.res);
        } else {
          item.reject(outcome.err);
        }
      });
  }

  get pending() {
    return this.queue.length;
  }

  get active() {
    return this.running;
  }
}

